create or replace function app_private.crm_customer_dto(p_actor uuid,p_learner uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare item jsonb;begin
 if not app_private.crm_can_access(p_actor,p_learner)then raise exception'NOT_FOUND';end if;
 select jsonb_build_object('learner_id',l.id,'person_id',l.person_id,'account_id',l.account_id,'display_name',p.display_name,'version',coalesce(c.version,1),'archived',coalesce(c.archived,false),'verified_contacts',(select coalesce(jsonb_agg(jsonb_build_object('channel',v.channel,'destination',v.destination,'verified',true)order by v.id),'[]'::jsonb)from app_private.verified_contacts v where v.account_id=l.account_id and v.revoked_at is null and v.verified_at is not null),'possible_duplicate_count',(select count(*)from app_private.crm_identity_matches m where p_learner in(m.left_learner_id,m.right_learner_id)and m.state='pending'),'open_follow_up_count',(select count(*)from app_private.follow_ups f where f.learner_id=l.id and f.state='open'),'balance_minor',finance_private.finance_json_total((select coalesce(sum((finance_private.finance_charge_balance(ch.id)->>'receivable_minor')::numeric),0)from finance_private.charges ch where ch.learner_id=l.id)))into item from app_private.learners l join app_private.people p on p.id=l.person_id left join app_private.crm_customers c on c.learner_id=l.id where l.id=p_learner;
 if item is null then raise exception'NOT_FOUND';end if;return item;end$$;
create or replace function app_private.finalize_export_render(p_export uuid,p_job uuid,p_lease uuid,p_size integer,p_hash text)returns jsonb language plpgsql security definer set search_path='' as $$declare prepared jsonb;s app_private.export_states%rowtype;begin prepared:=app_private.prepare_export_render(p_export,p_job,p_lease);if(prepared->>'blocked')::boolean then return prepared;end if;if p_size is null or p_size not between 1 and 26214400 or p_hash is null or p_hash!~'^[a-f0-9]{64}$'then raise exception 'VALIDATION_ERROR';end if;select * into s from app_private.export_states where export_id=p_export;if s.state='ready'and(s.size_bytes<>p_size or s.checksum_sha256<>p_hash)then raise exception 'VERSION_CONFLICT';end if;update app_private.export_states set state='ready',size_bytes=p_size,checksum_sha256=p_hash,safe_error_code=null,version=version+1 where export_id=p_export and state<>'ready';if found then perform app_private.enqueue_event(p_export,'export_ready',p_export,jsonb_build_object('export_id',p_export),'notifications.route');end if;return jsonb_build_object('blocked',false,'export_id',p_export,'state','ready');end$$;
create or replace function api.get_customer(p_learner_id uuid,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();customer jsonb;items jsonb;begin
 customer:=app_private.crm_customer_dto(actor,p_learner_id);if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 with history as(select distinct co.id,'completion'::text kind,co.submitted_at at,co.id reference,'Session completion submitted'::text summary from app_private.completions co join app_private.enrollments en on en.occurrence_id=co.occurrence_id where en.learner_id=p_learner_id union all select e.id,'enrollment'::text kind,e.created_at at,e.id reference,'Booking: '||s.title summary from app_private.enrollments e join app_private.occurrences o on o.id=e.occurrence_id join app_private.offers f on f.id=o.offer_id join app_private.subjects s on s.id=f.subject_id where e.learner_id=p_learner_id union all select r.id,'receipt',r.created_at,r.id,'Payment evidence submitted'from app_private.receipts r where r.learner_id=p_learner_id union all select f.id,'follow_up',f.created_at,f.id,'Follow-up: '||f.state from app_private.follow_ups f where f.learner_id=p_learner_id)
 select coalesce(jsonb_agg(x.item order by x.at desc,x.id desc),'[]'::jsonb)into items from(select id,at,jsonb_build_object('event_id',id,'event_type',kind,'occurred_at',at,'reference_id',reference,'summary',summary)item from history where p_cursor is null or(at,id)<(select h.at,h.id from history h where h.id=p_cursor limit 1)order by at desc,id desc limit p_limit)x;
 return jsonb_build_object('customer',customer,'history_page',jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'event_id'else null end));end$$;
notify pgrst,'reload schema';
create or replace function api.list_my_exports(p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb:='[]';e record;item jsonb;begin
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
 if p_cursor is not null and not exists(select 1 from app_private.export_jobs where id=p_cursor and requester_id=actor)then raise exception 'NOT_FOUND';end if;
 for e in select id from app_private.export_jobs where requester_id=actor and(p_cursor is null or(created_at,id)<(select x.created_at,x.id from app_private.export_jobs x where x.id=p_cursor))order by created_at desc,id desc loop
 begin item:=app_private.export_view(e.id,actor);items:=items||jsonb_build_array(item);exception when others then if sqlerrm not in('SESSION_REVOKED','NOT_FOUND','FORBIDDEN')then raise;end if;end;exit when jsonb_array_length(items)=p_limit;end loop;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'export_id'else null end);end$$;

